612	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
613		for i := range ps {
614			if ps[i].Name == name && ps[i].Version == version {
615				return &ps[i]
616			}
617		}
618		return nil
619	}
620	
621	func findJob(js []persistJob, id string) *persistJob {
622		for i := range js {
623			if js[i].ID == id {
624				return &js[i]
625			}
626		}
627		return nil
628	}
629	
630	func sameJobRequest(stored persistJob, request Job) bool {
631		return stored.Circuit == request.Circuit &&
632			stored.Version == request.Version &&
633			stored.Kind == request.Kind &&
634			stored.Attempt == request.Attempt &&
635			stored.CompiledHash == request.CompiledHash
636	}
637	
638	func circuitFromPersist(c persistCircuit) Circuit {
639		return Circuit{
640			Name: c.Name, Version: c.Version,
641			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
642			Frozen: c.Frozen, Description: c.Description,
643		}
644	}
645	
646	// circuitCopyMatches reports whether target is the same draft content that a
647	// copy of source would create: same description, same three counts and a
648	// semantically equal constraint definition. Definition equality follows the
649	// existing normalization semantics (terms merged per wire, coefficients
650	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
651	// definition differs from a present one.
652	func circuitCopyMatches(source, target persistCircuit) bool {
653		if source.Description != target.Description {
654			return false
655		}
656		if source.Constraints != target.Constraints ||
657			source.PublicInputs != target.PublicInputs ||
658			source.PrivateInputs != target.PrivateInputs {
659			return false
660		}
661		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
662	}
663	
664	// definitionsEqual compares two stored definitions for semantic equality.
665	// Both nil is equal; one nil and the other not is different. When both are
666	// present they are parsed through the existing normalization pipeline and
667	// compared by modulus, constraint count and each side's wire/coefficient
668	// pairs. The public/private layout is the source's; the caller has already
669	// confirmed the counts match.
670	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
671		if d1 == nil && d2 == nil {
672			return true
673		}
674		if d1 == nil || d2 == nil {
675			return false
676		}
677		p1, err := definitionFromPersist(*d1, public, private)
678		if err != nil {
679			return false
680		}
681		p2, err := definitionFromPersist(*d2, public, private)
682		if err != nil {
683			return false
684		}
685		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
686			return false
687		}
688		for i := range p1.constraints {
689			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
690				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
691				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
692				return false
693			}
694		}
695		return true
696	}
697	
698	// canonicalTermsEqual reports whether two normalized term slices are
699	// identical wire-by-wire and coefficient-by-coefficient.
700	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
701		if len(t1) != len(t2) {
702			return false
703		}
704		for i := range t1 {
705			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
706				return false
707			}
708		}
709		return true
710	}
711	
712	func setupFromPersist(p persistSetup) Setup {
713		return Setup{Name: p.Name, Version: p.Version}
714	}
