324	// layout cannot be represented (here M-1 public bumped to 1 private, summing
325	// past M once the constant wire is counted) makes the whole directory
326	// unreadable with ErrDataCorrupt; no query returns partial results and the
327	// original file is left byte-for-byte in place.
328	func TestOverflowRecordRefusedOnLoad(t *testing.T) {
