350				// json.Number keeps the digits exact; a float64 round-trip would
351				// rewrite M-1 as an imprecise value the strict int decoder rejects
352				// before the layout rule is reached.
353				rec["public_inputs"] = json.Number(strconv.Itoa(math.MaxInt - 1))
354				rec["private_inputs"] = json.Number("1") // 1 + (M-1) + 1 = M+1
355			}
356		}
