365			t.Fatalf("want ErrDataCorrupt, got %v", err)
366		}
367		if !strings.Contains(err.Error(), "not representable") {
368			t.Fatalf("corruption error must name the layout limit: %v", err)
369		}
370		left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
371		if rerr != nil {
372			t.Fatal(rerr)
373		}
374		if string(left) != string(bad) {
375			t.Fatal("refused read modified data.json")
376		}
377	}
