379	// TestOverflowRecordWithDefinitionRefusedOnLoad reproduces the original
380	// failure mode: a term-free definition committed against overflowing counts
381	// imported cleanly only because public+private wrapped negative, and the next
382	// read reported corruption via a definition mismatch. The explicit layout
383	// rule now names the same condition directly and still refuses the read.
384	func TestOverflowRecordWithDefinitionRefusedOnLoad(t *testing.T) {
385		dir := filepath.Join(t.TempDir(), "bench")
386		s, err := Open(dir)
387		if err != nil {
388			t.Fatal(err)
389		}
390		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1,
391			PublicInputs: math.MaxInt - 1, PrivateInputs: 0}); err != nil {
392			t.Fatal(err)
393		}
394		if _, err := s.ImportConstraints("c", 1, writeTempJSON(t, emptySidesDef)); err != nil {
395			t.Fatal(err)
396		}
397		if err := s.Close(); err != nil {
398			t.Fatal(err)
399		}
400	
401		env := readGenericEnv(t, dir)
402		rec := readFirstCircuit(env)
403		// Keep both counts as exact digits: a float64 round-trip would fail the
404		// strict int decoder instead of reaching the layout rule.
405		rec["public_inputs"] = json.Number(strconv.Itoa(math.MaxInt - 1))
406		rec["private_inputs"] = json.Number("1") // 1 + (M-1) + 1 = M+1
407		writeGenericEnv(t, dir, env)
408	
409		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
410			t.Fatalf("overflow layout with definition: want ErrDataCorrupt, got %v", err)
411		}
412	}
