688	// Concurrent import vs freeze must leave only a complete definition (old or
689	// new), never a frozen version with a half-applied or missing definition,
690	// and the on-disk state must reopen consistently.
691	func TestImportFreezeRaceCompleteness(t *testing.T) {
692		for iter := 0; iter < 20; iter++ {
693			dir := t.TempDir()
694			s, _ := Open(dir)
695			seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
696	
697			alt := `{"modulus":"7","constraints":[
698				{"a":[{"wire":1,"coeff":"3"}],"b":[],"c":[]}]}`
699			altPath := writeTempJSON(t, alt)
700	
701			var wg sync.WaitGroup
702			start := make(chan struct{})
703			wg.Add(2)
704			go func() {
705				defer wg.Done()
706				<-start
707				for range 200 {
708					if _, err := s.ImportConstraints("c", 1, altPath); err != nil {
709						if !errors.Is(err, ErrFrozen) {
710							t.Errorf("unexpected import error: %v", err)
711						}
712						return
713					}
714				}
715			}()
716			go func() {
717				defer wg.Done()
718				<-start
719				s.FreezeCircuit("c", 1)
720			}()
721			close(start)
722			wg.Wait()
723	
724			c, err := s.GetCircuit("c", 1)
725			if err != nil {
726				t.Fatal(err)
727			}
728			if !c.Frozen {
729				t.Fatalf("iter %d: version not frozen", iter)
730			}
731			def, err := s.GetDefinition("c", 1)
732			if err != nil {
733				t.Fatalf("iter %d: frozen version must keep a complete definition: %v", iter, err)
734			}
735			// Every import of the same alt content is byte-identical, and the
736			// original is fully distinct: a mixed body is impossible. Just check
737			// the modulus is coherent and it recompiles to a stable hash.
738			a1, err := s.CompileCircuit("c", 1)
739			if err != nil {
740				t.Fatalf("iter %d: compile after race: %v", iter, err)
741			}
742			a2, _ := s.CompileCircuit("c", 1)
743			if a1 != a2 {
744				t.Fatalf("iter %d: artifact not stable: %+v %+v", iter, a1, a2)
745			}
746			if len(def.Constraints) != 1 {
747				t.Fatalf("iter %d: bad definition %+v", iter, def)
748			}
749			s.Close()
750	
751			s2, err := Open(dir)
752			if err != nil {
753				t.Fatalf("iter %d: reopen: %v", iter, err)
754			}
755			got, err := s2.GetArtifact("c", 1)
756			s2.Close()
757			if err != nil || got != a1 {
758				t.Fatalf("iter %d: reopened artifact mismatch: %+v %v", iter, got, err)
759			}
760		}
761	}
