838	// TestParseWitnessValuesParsesOnceThroughBothEntries pins the refactor that
839	// removed the second numeric parse: validation now reduces each decimal
840	// string into a field residue once and evaluation reuses it. Arbitrarily
841	// long positive, negative, leading-zero and negative-zero representations
842	// congruent modulo the field must give the same verdict and first-failure
843	// position through the file entry and the direct-array entry, and an
844	// unsatisfying congruent family must stay unsatisfying at the same place.
845	func TestParseWitnessValuesParsesOnceThroughBothEntries(t *testing.T) {
846		s := openTestStore(t)
847		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef) // mod 7: x*y = 6
848		s.FreezeCircuit("c", 1)
849		a, _ := s.CompileCircuit("c", 1)
850		p := big.NewInt(7)
851		pow := new(big.Int).Exp(big.NewInt(10), big.NewInt(64), nil) // 10^64
852		k := new(big.Int).Mul(pow, p)                                // a multiple of the modulus
853	
854		// Satisfying residue pair (2,3) expressed as: huge positive, huge
855		// negative and leading zeros.
856		satisfying := []struct{ pub, priv string }{
857			{"2", "3"},
858			{new(big.Int).Add(big.NewInt(2), k).String(), new(big.Int).Sub(big.NewInt(3), k).String()},
859			{"00000000000000000000000000000000000000000002", "-0000000000000000000000000000000000000004"},
860			{"-0000000000000000000000000000000000000005", "0003"}, // -5 ≡ 2
861		}
862		// Negative zero is a legal representation of residue 0 and parses once
863		// to 0 like every other value.
864		if pw, err := parseWitnessValues([]string{"-0"}, nil, 1, 0, 7); err != nil || len(pw.public) != 1 || pw.public[0] != 0 {
865			t.Fatalf(`negative zero must parse once to residue 0, got %+v %v`, pw, err)
866		}
867		for i, tc := range satisfying {
868			direct, err := s.CheckInput("c", 1, a.Hash, Witness{Public: []string{tc.pub}, Private: []string{tc.priv}})
869			if err != nil {
870				t.Fatalf("satisfying case %d direct: %v", i, err)
871			}
872			doc := fmt.Sprintf(`{"public":["%s"],"private":["%s"]}`, tc.pub, tc.priv)
873			file, err := s.CheckInputFile("c", 1, a.Hash, writeTempJSON(t, doc))
874			if err != nil {
875				t.Fatalf("satisfying case %d file: %v", i, err)
876			}
877			if !direct.Satisfied || direct.FirstFailure != 0 || direct.Hash != a.Hash {
878				t.Fatalf("satisfying case %d direct verdict changed: %+v", i, direct)
879			}
880			if direct != file {
881				t.Fatalf("satisfying case %d: direct=%+v file=%+v", i, direct, file)
882			}
883		}
884	
885		// Unsatisfying pair (2,4) fails first at constraint 1; congruent huge
886		// rewrites must keep the unsatisfied verdict and the same position at
887		// both entries (unsatisfied is a completed check, exit-class success).
888		unsatisfying := []struct{ pub, priv string }{
889			{"2", "4"},
890			{new(big.Int).Sub(big.NewInt(2), k).String(), new(big.Int).Add(big.NewInt(4), k).String()},
891			{"-0000000000000000000000000000000000000005", "00000000000000000000000000000000000000000004"},
892		}
893		for i, tc := range unsatisfying {
894			direct, err := s.CheckInput("c", 1, a.Hash, Witness{Public: []string{tc.pub}, Private: []string{tc.priv}})
895			if err != nil {
896				t.Fatalf("unsatisfying case %d must be a completed check: %v", i, err)
897			}
898			doc := fmt.Sprintf(`{"public":["%s"],"private":["%s"]}`, tc.pub, tc.priv)
899			file, err := s.CheckInputFile("c", 1, a.Hash, writeTempJSON(t, doc))
900			if err != nil {
901				t.Fatalf("unsatisfying case %d file: %v", i, err)
902			}
903			if direct.Satisfied || direct.FirstFailure != 1 || direct.Hash != a.Hash {
904				t.Fatalf("unsatisfying case %d direct verdict changed: %+v", i, direct)
905			}
906			if direct != file {
907				t.Fatalf("unsatisfying case %d: direct=%+v file=%+v", i, direct, file)
908			}
909		}
910	}
911

