70	func (e *envelope) UnmarshalJSON(raw []byte) error {
71		// Reject repeated keys before decoding: encoding/json silently keeps the
72		// last value of a duplicate. The walk is layered so a repeated field is
73		// attributed to the record it belongs to (a duplicate "frozen" inside
74		// circuit #3, not a generic envelope complaint).
75		if err := scanEnvelopeDuplicates(raw); err != nil {
76			return err
77		}
78		var wire envelopeWire
79		if err := json.Unmarshal(raw, &wire); err != nil {
80			var se StoreError
81			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
82				return err // an inner record decoder already named the problem
83			}
84			return corruptf("data file envelope is not valid JSON: %v", err)
85		}
86		e.Format = wire.Format
87		e.Setups = wire.Setups
88		e.Jobs = wire.Jobs
89		e.Artifacts = wire.Artifacts
90		if wire.Circuits == nil {
91			e.Circuits = nil
92		} else {
93			e.Circuits = make([]persistCircuit, len(wire.Circuits))
94		}
95		for i, craw := range wire.Circuits {
96			var record persistCircuit
97			if err := json.Unmarshal(craw, &record); err != nil {
98				var se StoreError
99				if errors.As(err, &se) {
100					// Re-tag as one corruption error carrying the record index,
101					// so the detail survives errors.As unwrapping in loadLocked.
102					return StoreError{Kind: ErrDataCorrupt.Kind,
103						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
104				}
105				return corruptf("circuit record #%d: %v", i+1, err)
106			}
107			e.Circuits[i] = record
108		}
109		return nil
110	}
111	
112	// envelopeTopFields are the five fields an envelope may carry. Their
113	// canonical (standard lowercase) spellings are the wire tags on envelope and
114	// envelopeWire; JSON keys are tokenized after unescaping.
115	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
116	
117	// canonicalEnvelopeField reports the standard lowercase name of one of the
118	// five envelope fields when key names it under any ASCII letter-case spelling
119	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
120	// tokenizer, so an escaped spelling of any such form lands here too. A
121	// non-canonical key (different length or a mismatching byte, including
122	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
123	func canonicalEnvelopeField(key string) string {
124		for _, field := range envelopeTopFields {
125			if len(key) != len(field) {
126				continue
127			}
128			i := 0
129			for i < len(key) {
130				c := key[i]
131				if c >= 'A' && c <= 'Z' {
132					c += 'a' - 'A'
133				}
134				if c != field[i] {
135					break
136				}
137				i++
138			}
139			if i == len(field) {
140				return field
141			}
142		}
143		return ""
144	}
145	
146	// envelopeFieldLookalike reports the standard lowercase name of one of the
147	// five envelope fields when key names it under a spelling encoding/json's
148	// struct-tag matching would fold onto the field but which is not an accepted
149	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
150	// matching folds with the Unicode simple case-folding rules
151	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
152	// the JSON escape u017f — keys arrive here already unescaped) names the
153	// circuits field exactly like "circuits", even standing alone. Such a
154	// lookalike is damage whatever its value: a later "circuitſ": [] would
155	// otherwise override a populated circuits array through last-value-wins and
156	// the records would vanish on the next commit. A key that does not fold onto
157	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
158	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
159	// the ordinary unknown-member handling.
160	func envelopeFieldLookalike(key string) string {
161		if canonicalEnvelopeField(key) != "" {
162			return "" // an accepted ASCII spelling, not a lookalike
163		}
164		for _, field := range envelopeTopFields {
165			if strings.EqualFold(key, field) {
166				return field
167			}
168		}
169		return ""
170	}
171	
172	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
173	// repeated object key. The five known top-level fields are identified case-
174	// insensitively: two spellings that differ only in ASCII letter case (both
175	// keys already JSON-unescaped at this point) are the same field, in whatever
176	// order they appear and whether or not their values agree, so a later
177	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
178	// json's last-value-wins struct matching. Such a pair is reported as a
179	// duplicated top-level field named by its standard lowercase spelling.
180	//
181	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
182	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
183	// directly written or ſ-escaped) is rejected outright as data corruption:
184	// encoding/json would match it onto the field, so ignoring it as unknown
185	// could let its value replace the real one (an empty array hiding every
186	// record), and accepting it would let the records vanish on the next commit.
187	// The rule holds for the lookalike appearing alone — value a legal record, an
188	// empty array or null alike — and for it appearing beside the canonical
189	// spelling or an ASCII case variant, in either order and whether the values
190	// agree. The error names both the standard field and the actual spelling.
191	//
192	// Circuit and job records are scanned one record at a time through their
193	// shared per-record readers — the record's own top-level keys are checked
194	// here (with the record's 1-based index, or the job's id, reported) by
195	// scanCircuitArray and the shared job reader scanJobArray in job_record.go,
196	// while a nested value such as a constraint definition or an unknown job
197	// member's object is skipped and left to its own strict decoder. Every other
198	// envelope member is scanned recursively so a duplicated key anywhere in
199	// committed data fails the read instead of silently resolving to its last
200	// value.
201	func scanEnvelopeDuplicates(raw []byte) error {
202		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
203		dec.UseNumber()
204		open, err := dec.Token()
205		if err != nil || open != json.Delim('{') {
206			return corruptf("data file envelope must be a JSON object")
207		}
208		// Exact spellings retain the pre-existing check for unknown keys;
209		// canonical names remember a known field's first occurrence regardless
210		// of the case it was written in.
211		seenTop := make(map[string]bool)
212		seenCanonical := make(map[string]bool)
213		for dec.More() {
214			keyTok, err := dec.Token()
215			if err != nil {
216				return corruptf("data file envelope is not valid JSON: %v", err)
217			}
218			key, ok := keyTok.(string)
219			if !ok {
220				return corruptf("data file envelope is not valid JSON")
221			}
222			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
223			// matching would read as a known field ("circuitſ" with long s,
224			// directly written or ſ-escaped) before anything else. It is damage
225			// even on its own and whatever its value — a legal record, an empty
226			// array or null — and whether it precedes or follows the canonical or
227			// an ASCII case-variant spelling: the read may neither ignore it as an
228			// unknown member nor choose one of the values and carry on.
229			if canonical := envelopeFieldLookalike(key); canonical != "" {
230				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
231					canonical, key)
232			}
233			if canonical := canonicalEnvelopeField(key); canonical != "" {
234				if seenCanonical[canonical] {
235					if key == canonical {
236						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
237					}
238					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
239						canonical, key)
240				}
241				seenCanonical[canonical] = true
242				if canonical == "circuits" {
243					if err := scanCircuitArray(dec); err != nil {
244						return err
245					}
246					continue
247				}
248				if canonical == "jobs" {
249					if err := scanJobArray(dec); err != nil {
250						return err
251					}
252					continue
253				}
254				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
255					return err
256				}
257				continue
258			}
259			if seenTop[key] {
260				return corruptf("data file envelope contains duplicate field %q", key)
261			}
262			seenTop[key] = true
263			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
264				return err
265			}
266		}
267		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
268			return corruptf("data file envelope is not valid JSON")
269		}
270		if _, err := dec.Token(); err != io.EOF {
271			return corruptf("data file envelope is not valid JSON: trailing data after the object")
272		}
273		return nil
274	}
275	
276	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
277	// recursively rejecting duplicate object keys.
278	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
279		tok, err := dec.Token()
280		if err != nil {
281			return corruptf("%s is not valid JSON: %v", what, err)
282		}
283		delim, ok := tok.(json.Delim)
284		if !ok {
285			return nil // scalar (including null)
286		}
287		switch delim {
288		case '{':
289			seen := make(map[string]bool)
290			for dec.More() {
291				keyTok, err := dec.Token()
292				if err != nil {
293					return corruptf("%s is not valid JSON: %v", what, err)
294				}
295				key, ok := keyTok.(string)
296				if !ok {
297					return corruptf("%s is not valid JSON", what)
298				}
299				if seen[key] {
300					return corruptf("%s contains duplicate field %q", what, key)
301				}
302				seen[key] = true
303				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
304					return err
305				}
306			}
307			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
308				return corruptf("%s is not valid JSON", what)
309			}
310		case '[':
311			index := 0
312			for dec.More() {
313				index++
314				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
315					return err
316				}
317			}
318			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
319				return corruptf("%s is not valid JSON", what)
320			}
321		}
322		return nil
323	}
324	
325	type persistTerm struct {
326		Wire  int    `json:"wire"`
327		Coeff string `json:"coeff"`
328	}
329	
330	type persistConstraint struct {
331		A []persistTerm `json:"a"`
332		B []persistTerm `json:"b"`
333		C []persistTerm `json:"c"`
334	}
335	
336	// persistDefinition is the canonical, already-validated constraint set bound
337	// to one circuit version. The public/private partition is owned by the
338	// circuit record and is deliberately not duplicated here, so it can never
339	// drift from the declared counts.
340	type persistDefinition struct {
341		Modulus     string              `json:"modulus"`
342		Constraints []persistConstraint `json:"constraints"`
343	}
344	
345	// persistArtifact is a compiled artifact: the version's identity and
346	// constraint count bound to its recomputable SHA-256 hash.
347	type persistArtifact struct {
348		Name        string `json:"name"`
349		Version     int    `json:"version"`
350		Modulus     int64  `json:"modulus"`
351		Constraints int    `json:"constraints"`
352		Hash        string `json:"hash"`
353	}
354	
355	type persistSetup struct {
356		Name    string `json:"name"`
357		Version int    `json:"version"`
358	}
359	
360	// Store is a persistent workbench backed by one local data directory.
361	//
362	// All operations are safe for concurrent use by multiple goroutines and by
363	// several processes pointed at the same directory: an in-process mutex plus a
364	// process-shared flock serialize commits, and every commit is an atomic
365	// temp-file/fsync/rename replacement. Open the directory with Open and call
366	// Close when done.
367	type Store struct {
368		dir  string
369		mu   sync.Mutex
370		lock *os.File
371	
372		data envelope
373	}
374	
375	// resolveDataDir turns the Open argument into the absolute physical
376	// directory the store will be permanently pinned to.
377	//
378	// The argument is resolved exactly the way the kernel reaches it on an
379	// open(2) — relative components anchored to the process's current working
380	// directory at Open time, one component at a time, every symlink expanded at
381	// the position where the walk meets it. No lexical Clean is applied first:
382	// filepath.Abs/Clean would fold "entry/.." before the symlink was ever
383	// examined, so a ".." standing after a symlink pops the link's resolved
384	// target rather than the link's own spelling, and a/link/../x cannot be made
385	// to name a/x and select another data directory. Any trailing segment that
386	// does not exist yet (a data directory to be created by Open, or a
387	// not-yet-existing parent) is appended verbatim to the resolved physical
388	// prefix, and MkdirAll creates it beneath that prefix; a ".." after such a
389	// missing component cannot be walked faithfully (the kernel reports ENOENT
390	// there instead of folding the literal path) and fails the resolution. A
391	// dangling entry link — the entry itself is a symlink whose target does not
392	// exist — resolves through the link target's spelling and is created there.
393	func resolveDataDir(dir string) (string, error) {
394		resolved, err := resolveExistingPrefix(dir)
395		if err != nil {
396			return "", err
397		}
398		if !filepath.IsAbs(resolved) {
399			// The walk itself stayed relative to the Open-time working directory;
400			// only now, after every symlink has been expanded and every ".."
401			// popped in walk order, anchor the result absolutely for pinning.
402			resolved, err = filepath.Abs(resolved)
403			if err != nil {
404				return "", err
405			}
406		}
407		return resolved, nil
408	}
409	
410	// maxDataDirLinks bounds symlink expansion while resolving the data
411	// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
412	// rather than loop forever.
413	const maxDataDirLinks = 255
414	
415	// resolveExistingPrefix walks path the way a kernel path walk reaches it,
416	// accepting both absolute and Open-cwd-relative paths. Symlinks are expanded
417	// inline where the walk meets them and ".." pops the directory the walk is
418	// actually standing in (a link target, not the link spelling). Unlike
419	// filepath.EvalSymlinks the walk tolerates a missing tail: at the first
420	// component that cannot be Lstat'd, that component and the remaining literal
421	// components are appended to the resolved prefix so Open can create the chain
422	// with MkdirAll — unless the remainder contains "..", which could not be
423	// resolved against a non-existent entry and is an error.
424	func resolveExistingPrefix(path string) (string, error) {
425		volLen := len(filepath.VolumeName(path))
426		pathSeparator := string(os.PathSeparator)
427		if volLen < len(path) && os.IsPathSeparator(path[volLen]) {
428			volLen++
429		}
430		vol := path[:volLen] // "/" (or a drive/UNC root elsewhere); "" when relative
431		dest := vol
432		linksWalked := 0
433		for start, end := volLen, volLen; start < len(path); start = end {
434			for start < len(path) && os.IsPathSeparator(path[start]) {
435				start++
436			}
437			end = start
438			for end < len(path) && !os.IsPathSeparator(path[end]) {
439				end++
440			}
441			if end == start {
442				break
443			}
444			comp := path[start:end]
445			if comp == "." {
446				continue
447			}
448			if comp == ".." {
449				// Pop what the walk has actually reached; symlinks have already
450				// been expanded into dest, so this removes the target, never the
451				// link spelling.
452				r := -1
453				for i := len(dest) - 1; i >= volLen; i-- {
454					if os.IsPathSeparator(dest[i]) {
455						r = i
456						break
457					}
458				}
459				if r < volLen || dest[r+1:] == ".." {
460					if len(dest) > volLen {
461						dest += pathSeparator
462					}
463					dest += ".."
464				} else {
465					dest = dest[:r]
466				}
467				continue
468			}
469	
470			if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
471				dest += pathSeparator
472			}
473			dest += comp
474	
475			fi, err := os.Lstat(dest)
476			if err != nil {
477				if !os.IsNotExist(err) {
478					return "", err
479				}
480				// Missing tail: append the remainder literally, refusing a
481				// remainder containing ".." (unresolvable against this absent
482				// entry), and let MkdirAll create the chain.
483				for r := end; r < len(path); {
484					for r < len(path) && os.IsPathSeparator(path[r]) {
485						r++
486					}
487					s := r
488					for r < len(path) && !os.IsPathSeparator(path[r]) {
489						r++
490					}
491					switch path[s:r] {
492					case "", ".":
493					case "..":
494						return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", path, comp)
495					default:
496						dest += pathSeparator + path[s:r]
497					}
498				}
499				return filepath.Clean(dest), nil
500			}
501			if fi.Mode()&os.ModeSymlink == 0 {
502				if !fi.Mode().IsDir() && end < len(path) {
503					return "", fmt.Errorf("cannot resolve %q: %q is not a directory", path, comp)
504				}
505				continue
506			}
507			linksWalked++
508			if linksWalked > maxDataDirLinks {
509				return "", fmt.Errorf("cannot resolve %q: too many symlinks", path)
510			}
511			link, err := os.Readlink(dest)
512			if err != nil {
513				return "", err
514			}
515			// Expand the link exactly at the walk position: the still-queued
516			// components (including any "..") continue from the target rather
517			// than from the link spelling.
518			path = link + path[end:]
519			switch {
520			case len(link) > 0 && os.IsPathSeparator(link[0]):
521				volLen = 1
522				vol = path[:1]
523				dest = vol
524				end = 1
525			default:
526				if v := filepath.VolumeName(link); v != "" {
527					if len(link) > len(v) && os.IsPathSeparator(link[len(v)]) {
528						v += string(os.PathSeparator)
529					}
530					volLen = len(v)
531					vol = v
532					dest = vol
533					end = volLen
534					break
535				}
536				// Relative link: it names a path from the directory holding the
537				// link, which is dest without the link's own component.
538				r := -1
539				for i := len(dest) - 1; i >= volLen; i-- {
540					if os.IsPathSeparator(dest[i]) {
541						r = i
542						break
543					}
544				}
545				if r < volLen {
546					dest = vol
547				} else {
548					dest = dest[:r]
549				}
550				end = 0
551			}
552		}
553		return filepath.Clean(dest), nil
554	}
555	
556	// Open opens (creating if needed) the workbench data in dir. If the
557	// directory does not exist it is created. Existing committed data is loaded
558	// and fully validated before Open returns; on a corrupt, truncated or
559	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
560	// leaves every file in the directory untouched.
561	//
562	// dir is resolved against the process's current working directory at Open
563	// time and pinned for the store's lifetime: a relative path such as
564	// "bench-data" names one fixed directory from the moment Open succeeds, and
565	// later working-directory changes never redirect the store's reads, writes,
566	// lock or Dir to another location.
567	//
568	// The pinning is to the actual directory opened, not to the literal path
569	// spelling: symlinks already present in the file system — whether dir itself
570	// is a link or one of its parent directories is — are resolved segment by
571	// segment at Open time, and Dir reports the resulting absolute physical
572	// directory. Repointing or removing an entry link afterwards never moves the
573	// store: queries, commits, the lock file and compiled-artifact bindings keep
574	// using the original directory even after the link changes or vanishes. A
575	// ".." following a symlink is resolved the way the kernel walk reaches it
576	// (the already-resolved link target is popped), never by lexical folding of
577	// the literal path, so it cannot select a different data directory. A
578	// not-yet-existing data directory named through a valid (possibly
579	// symlinked) parent is created under the parent's physical location. Paths
580	// to constraint definitions and input files passed to individual operations
581	// are not pinned this way — they keep being resolved against the caller's
582	// working directory at call time.
583	func Open(dir string) (*Store, error) {
584		if dir == "" {
585			return nil, invalidf("data directory must not be empty")
586		}
587		// Resolve and pin the physical location now, before anything else can
588		// change. resolveDataDir walks the argument the way the kernel reaches
589		// it — relative to the process working directory at Open time, symlinks
590		// expanded segment by segment in walk order and ".." popped in place — so
591		// a later chdir, a repointed or deleted entry link, or a ".." sitting
592		// after a symlink cannot move reads, writes, the lock or Dir onto another
593		// directory. The result is absolute and names the real directory opened.
594		dir, err := resolveDataDir(dir)
595		if err != nil {
596			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
597		}
598		if err := os.MkdirAll(dir, 0o755); err != nil {
599			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
600		}
601		lockPath := filepath.Join(dir, dirLockFile)
602		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
603		if err != nil {
604			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
605		}
606		// Serialize against other processes while we read / validate.
607		if err := lockExclusive(lock); err != nil {
608			lock.Close()
609			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
610		}
611	
612		s := &Store{dir: dir, lock: lock}
613		if err := s.loadLocked(); err != nil {
614			unlockLock(lock)
615			lock.Close()
616			return nil, err
617		}
618		// The lock is taken again per operation; holding it for the store's
619		// lifetime would forbid two open handles on one directory.
620		if err := unlockLock(lock); err != nil {
621			lock.Close()
622			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
623		}
624		return s, nil
625	}
626	
627	// Close releases the directory lock. It does not discard committed data.
628	func (s *Store) Close() error {
629		s.mu.Lock()
630		defer s.mu.Unlock()
631		if s.lock == nil {
632			return nil
633		}
634		var first error
635		if err := unlockLock(s.lock); err != nil {
636			first = err
637		}
638		if err := s.lock.Close(); err != nil && first == nil {
639			first = err
640		}
641		s.lock = nil
642		return first
643	}
644	
645	// Dir reports the data directory backing the store.
646	func (s *Store) Dir() string { return s.dir }
647	
648	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
649	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
650	
651	// loadLocked reads and validates the committed file. Caller must hold the
652	// exclusive flock; the in-process mutex is taken by the public Open path.
653	func (s *Store) loadLocked() error {
654		raw, err := os.ReadFile(s.dataPath())
655		if errors.Is(err, os.ErrNotExist) {
656			s.data = envelope{Format: FormatVersion}
657			return nil
658		}
659		if err != nil {
660			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
661		}
662		if len(strings.TrimSpace(string(raw))) == 0 {
663			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
664		}
665	
666		var env envelope
667		if err := json.Unmarshal(raw, &env); err != nil {
668			// Shape failures surfaced by the persisted-definition decoders are
669			// integrity failures, not JSON syntax errors; report their detail
670			// instead of the generic "not valid JSON" wording.
671			var se StoreError
672			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
673				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
674			}
675			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
676		}
677		if env.Format == 0 {
678			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
679		}
680		if env.Format != FormatVersion {
681			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
682				s.dataPath(), env.Format, FormatVersion)
683		}
684		if err := validateEnvelope(env); err != nil {
685			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
686		}
687		s.data = env
688		return nil
689	}
690	
691	// commitLocked writes the pending state atomically: temp file → fsync →
692	// rename → fsync directory. Caller must hold both the in-process mutex and
693	// the exclusive flock; all in-memory mutations must already have happened and
694	// been rule-checked, so a failure here occurs before any success is reported.
695	func (s *Store) commitLocked() error {
696		s.data.Format = FormatVersion
697		// Stable output: records are stored sorted so files are deterministic.
698		sortEnvelope(&s.data)
699	
700		payload, err := json.MarshalIndent(&s.data, "", "  ")
701		if err != nil {
702			return fmt.Errorf("cannot encode data: %w", err)
703		}
704		payload = append(payload, '\n')
705	
706		tmp := s.tmpPath()
707		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
708		if err != nil {
709			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
710		}
711		if _, err := f.Write(payload); err != nil {
712			f.Close()
713			os.Remove(tmp)
714			return fmt.Errorf("cannot write staged data: %w", err)
715		}
716		if err := f.Sync(); err != nil {
717			f.Close()
718			os.Remove(tmp)
719			return fmt.Errorf("cannot flush staged data: %w", err)
720		}
721		if err := f.Close(); err != nil {
722			os.Remove(tmp)
723			return fmt.Errorf("cannot finish staged data: %w", err)
724		}
725		if err := os.Rename(tmp, s.dataPath()); err != nil {
726			os.Remove(tmp)
727			return fmt.Errorf("cannot commit data file: %w", err)
728		}
729		if err := syncDir(s.dir); err != nil {
730			// The rename already happened; lack of dir fsync only weakens crash
731			// durability, never correctness of what is visible now.
732			return nil
733		}
734		return nil
735	}
736	
737	// withLock runs fn under the in-process mutex and an exclusive flock, then
738	// atomically commits when fn requests it. The on-disk state is re-read after
739	// acquiring the lock, so concurrent commits from another process or another
740	// handle are always observed. Operations validate before mutating; a rejected
741	// operation (commit=false or an error) writes nothing and leaves committed
742	// state unchanged.
743	func (s *Store) withLock(fn func() (commit bool, err error)) error {
744		s.mu.Lock()
745		defer s.mu.Unlock()
746		if s.lock == nil {
747			return invalidf("store is closed")
748		}
749		if err := lockExclusive(s.lock); err != nil {
750			return fmt.Errorf("cannot lock data directory: %w", err)
751		}
752		defer unlockLock(s.lock)
753	
754		if err := s.loadLocked(); err != nil {
755			return err
756		}
757		commit, err := fn()
758		if err != nil {
759			return err
760		}
761		if !commit {
762			return nil
763		}
764		return s.commitLocked()
765	}
766	
767	// withLockRead runs fn under a shared flock over freshly reloaded state.
768	func (s *Store) withLockRead(fn func() error) error {
769		s.mu.Lock()
770		defer s.mu.Unlock()
771		if s.lock == nil {
772			return invalidf("store is closed")
773		}
774		if err := lockShared(s.lock); err != nil {
775			return fmt.Errorf("cannot lock data directory: %w", err)
776		}
777		defer unlockLock(s.lock)
778		if err := s.loadLocked(); err != nil {
779			return err
780		}
781		return fn()
782	}
783	
784	func sortEnvelope(env *envelope) {
785		sort.Slice(env.Circuits, func(i, j int) bool {
786			if env.Circuits[i].Name != env.Circuits[j].Name {
787				return env.Circuits[i].Name < env.Circuits[j].Name
788			}
789			return env.Circuits[i].Version < env.Circuits[j].Version
790		})
791		sort.Slice(env.Setups, func(i, j int) bool {
792			if env.Setups[i].Name != env.Setups[j].Name {
793				return env.Setups[i].Name < env.Setups[j].Name
794			}
795			return env.Setups[i].Version < env.Setups[j].Version
796		})
797		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
798		sort.Slice(env.Artifacts, func(i, j int) bool {
799			if env.Artifacts[i].Name != env.Artifacts[j].Name {
800				return env.Artifacts[i].Name < env.Artifacts[j].Name
801			}
802			return env.Artifacts[i].Version < env.Artifacts[j].Version
803		})
804	}
805	
806	// validateEnvelope re-checks every invariant on load so a tampered or
807	// hand-edited file cannot bypass the domain rules.
808	func validateEnvelope(env envelope) error {
809		seenCircuit := make(map[[2]string]bool)
810		circuitOK := make(map[[2]string]bool)
811		for i, c := range env.Circuits {
812			key := [2]string{c.Name, itoa(c.Version)}
813			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
814				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
815			}
816			if c.Version <= 0 {
817				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
818			}
819			if seenCircuit[key] {
820				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
821			}
822			seenCircuit[key] = true
823			if c.Constraints <= 0 {
824				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
825			}
826			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
827				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
828			}
829			// The same representability rule the write path enforces: wire 0 plus
830			// every declared input must fit inside the platform's int. A record
831			// beyond that bound can never have been written by this build and
832			// cannot be checked safely, so the directory is corrupt rather than
833			// silently narrowed or read with a wrapped-around layout.
834			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
835				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
836					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
837			}
838			if c.Definition != nil {
839				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
840					return err
841				}
842			}
843			circuitOK[key] = true
844		}
845		seenSetup := make(map[[2]string]bool)
846		for i, p := range env.Setups {
847			key := [2]string{p.Name, itoa(p.Version)}
848			if !circuitOK[key] {
849				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
850			}
851			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
852			if c == nil || !c.Frozen {
853				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
854			}
855			if seenSetup[key] {
856				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
857			}
858			seenSetup[key] = true
859		}
860		seenJob := make(map[string]bool)
861		for i, j := range env.Jobs {
862			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
863				return fmt.Errorf("job #%d has an empty or blank id", i+1)
864			}
865			if seenJob[j.ID] {
866				return fmt.Errorf("job %q appears more than once", j.ID)
867			}
868			seenJob[j.ID] = true
869			if j.Kind != "prove" {
870				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
871			}
872			if j.Attempt <= 0 {
873				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
874			}
875			key := [2]string{j.Circuit, itoa(j.Version)}
876			if !circuitOK[key] {
877				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
878			}
879			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
880			if c == nil || !c.Frozen {
881				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
882			}
883			if !seenSetup[key] {
884				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
885			}
886			// A recorded compiled-artifact binding must still resolve against the
887			// pinned version's artifact; a dangling or mismatched binding makes
888			// the file unreadable rather than silently dropping the binding.
889			if j.CompiledHash != "" {
890				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
891				if artifact == nil {
892					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
893				}
894				if artifact.Hash != j.CompiledHash {
895					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
896						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
897				}
898			}
899		}
900		seenArtifact := make(map[[2]string]bool)
901		for i, a := range env.Artifacts {
902			key := [2]string{a.Name, itoa(a.Version)}
903			if !circuitOK[key] {
904				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
905			}
906			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
907			if c == nil || !c.Frozen {
908				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
909			}
910			if seenArtifact[key] {
911				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
912			}
913			seenArtifact[key] = true
914			if c.Definition == nil {
915				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
916			}
917			if a.Constraints != c.Constraints {
918				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
919					a.Name, a.Version, a.Constraints, c.Constraints)
920			}
921			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
922			if err != nil {
923				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
924			}
925			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
926				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
927			}
928			wantHash := artifactHash(a.Name, a.Version, def)
929			if a.Hash != wantHash {
930				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
931					a.Name, a.Version, a.Hash, wantHash)
932			}
933		}
934		return nil
935	}
936	
937	// validatePersistDefinition re-validates a stored definition against its
938	// version's declared counts: prime modulus, in-range wires and an exact
939	// constraint count match.
940	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
941		parsed, err := definitionFromPersist(*def, public, private)
942		if err != nil {
943			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
944		}
945		if !parsed.compatibleWith(constraints, public, private) {
946			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
947		}
948		return nil
949	}
950	
951	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
952		for i := range cs {
953			if cs[i].Name == name && cs[i].Version == version {
954				return &cs[i]
955			}
956		}
957		return nil
958	}
959	
960	func itoa(v int) string { return fmt.Sprintf("%d", v) }
961

